const DEADLINE_MS = 1500;
async function loadFeed(cursor?: string) {
  renderSkeleton({ fixedHeights: true }); // no layout shift
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), DEADLINE_MS);
  try {
    const res = await fetch(`/v1/feed?cursor=${cursor ?? ""}`, {
      signal: ctrl.signal,
      headers: { "Idempotency-Key": getOrCreateKey("feed") }
    });
    const body = await res.json();
    if (body.meta?.stale) showStaleBadge();
    renderItems(body, { stableKeys: true }); // cursor, not index
  } catch (e) {
    renderRetry({ cause: toTypedError(e), actionId: true });
  } finally {
    clearTimeout(t);
  }
}
